import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  // Root container – position/rotation/scale will be applied by the adapter.
  const root = new Group();

  // --- Geometry & Material -------------------------------------------------
  // Use the aspect ratio of the source image (512 / 320 ≈ 1.6) for a proportional plane.
  const planeAspect = 512 / 320;
  const geometry = new PlaneGeometry(planeAspect, 1);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff, transparent: true });
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously; the function stays synchronous.
  let texture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Text -----------------------------------------------------------------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const textObjects = [];

  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? 39;
    const color = (config.visualSpec?.colors?.paper) || '#e8ecf2';
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize,
      color,
      align: 'center',
    });

    // Slightly lift the text above the plane to avoid Z‑fighting.
    txt.position.set(0, 0, 0.01);
    root.add(txt);
    textObjects.push(txt);
  }

  // --- Cinematic Primitives -------------------------------------------------
  const primitiveCleanups = [];

  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const handler = ctx.primitives[primitive.name];
      if (typeof handler === 'function') {
        const result = handler(root, primitive.params ?? {});
        if (result && typeof result.cleanup === 'function') {
          primitiveCleanups.push(result.cleanup);
        }
      }
    }
  }

  // --- UserData ------------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose Three.js resources.
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();

    // Dispose any text objects (they hold their own resources).
    for (const obj of textObjects) {
      if (obj.parent) obj.parent.remove(obj);
    }

    // Run primitive cleanups.
    for (const clean of primitiveCleanups) clean();

    // Clear handlers reference.
    root.userData.handlers = {};
  };

  return root;
}
